(* [comment removed for export] *)
Section SO2A.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x5 x10 x11 x14 x15 x16 x18 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : amem) (WK nbS : Z) (ws : list Z) (js : list byte).
  Variable Q : machine_state -> Prop.
  Hypothesis HWK : ablk WK (WK + 8704).
  Hypothesis HNS : 1 <= nbS <= 256.
  Hypothesis LWS : zlen ws = nbS.
  Hypothesis WSR : forall i, 0 <= i < nbS -> 0 <= Znth i ws <= 12.
  Hypothesis LJS : length js = 256%nat.
  Hypothesis HWB0 : bytes_at asegs m (WK + 992) (map (Z_to_bv 8) ws).
  Hypothesis ZWK : zshadow m WK 8704.
  Hypothesis RWK : rng RNG WK 8704.
  Hypothesis RWKs : rng RNG (shad WK) (nshad (8704 + WK mod 8)).
  Notation SINV m1 rs0 sorted := (u32arr asegs m1 (WK + 676) (map (Z_to_bv 64) rs0) /\ length rs0 = 15%nat
                           /\ u8arr asegs m1 (WK + 736) (BM.omerge js sorted) /\ length sorted = 256%nat
                           /\ munch [(WK + 676, WK + 992)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1).
  Notation LSO s m1 x6 x12 x13 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp (Z_to_bv 64 s) x6 (Z_to_bv 64 (WK + 736)) (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10
             (Z_to_bv 64 (WK + 680)) x12 x13 x14 x15 x16 (Z_to_bv 64 nbS) x18 (Z_to_bv 64 (WK + 992)) x20 x21 x22 x23
             (Z_to_bv 64 2147450880) x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 0x81878) fc None m1 (seg_rom asegs)).

  Lemma soA2_loop : forall f s rs0 sorted m1 r (x6 x12 x13 : word),
    sort2 f s ws rs0 sorted = Ok r -> Z.of_nat f = nbS - s -> 0 <= s < nbS ->
    (forall i, 0 <= i < 15 -> 0 <= Znth i rs0 <= 256) -> SINV m1 rs0 sorted ->
    (forall m2 rs0' sorted' (y6 y12 y13 : word), r = (rs0', sorted') -> SINV m2 rs0' sorted' ->
       evtF asegs RNG Q
         (MS (mkR x1 (Z_to_bv 64 SPA) gp tp (Z_to_bv 64 nbS) y6 (Z_to_bv 64 (WK + 736)) (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10
                  (Z_to_bv 64 (WK + 680)) y12 y13 x14 x15 x16 (Z_to_bv 64 nbS) x18 (Z_to_bv 64 (WK + 992)) x20 x21 x22 x23
                  (Z_to_bv 64 2147450880) x25 x26 x27 x28 x29 x30 x31)
             F (Z_to_bv 64 0x81904) fc None m2 (seg_rom asegs))) ->
