Section RV0A.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x5 x6 x7 x13 x18 x19 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : amem) (WK wEnd rsc : Z) (rank : list Z).
  Variable Q : machine_state -> Prop.
  Hypothesis HWK : ablk WK (WK + 8704).
  Hypothesis HWE : 2 <= wEnd <= 13.
  Hypothesis HRSC : 0 <= 1 + rsc /\ wEnd - 1 + rsc <= 12.
  Hypothesis LRK : length rank = 13%nat.
  Hypothesis RKR : forall i, 0 <= i < 13 -> 0 <= Znth i rank <= 256.
  Hypothesis RKA0 : u32arr asegs m (WK + 624) (map (Z_to_bv 64) rank).
  Hypothesis ZWK : zshadow m WK 8704.
  Hypothesis RWK : rng RNG WK 8704.
  Hypothesis RWKs : rng RNG (shad WK) (nshad (8704 + WK mod 8)).
  Notation VINV m1 rv w := (rv_atA m1 WK rv (fun j => 1 <= j < w) /\ length rv = 156%nat
                           /\ munch [(WK, WK + 624)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1).

  Lemma rvA0_loop : forall f w next rv m1 r (x12 x15 x17 : word),
    rank_val0 f w next rsc rank rv = Ok r -> Z.of_nat f = wEnd - w -> 1 <= w < wEnd -> 0 <= next <= 1048576 * (w - 1) ->
    VINV m1 rv w ->
    (forall m2 rv' (y10 y11 y12 y13 y14 y15 y16 y17 : word), r = rv' -> VINV m2 rv' wEnd ->
       evtF asegs RNG Q
         (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) y10 y11 y12 y13 y14 y15 y16 y17
                  x18 x19 x20 x21 x22 x23 (Z_to_bv 64 2147450880) x25 x26 x27 x28 x29 x30 x31)
             F (Z_to_bv 64 0x819c0) fc None m2 (seg_rom asegs))) ->
    evtF asegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) (Z_to_bv 64 (w + rsc))
               (Z_to_bv 64 (WK + 624 + 4 * w)) x12 (Z_to_bv 64 (WK + 624 + 4 * w)) (Z_to_bv 64 (wEnd - w)) x15
               (Z_to_bv 64 next) x17 x18 x19 x20 x21 x22 x23 (Z_to_bv 64 2147450880) x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 0x81950) fc None m1 (seg_rom asegs)).
