(* [comment removed for export] *)
Definition PRwA (wEnd mB c w : Z) : Z -> Prop := fun j =>
  (1 <= j < wEnd) \/ (exists c' w', mB <= c' /\ ((c' < c /\ 1 <= w' < wEnd) \/ (c' = c /\ 1 <= w' < w)) /\ j = rv_idx c' w').

(* [comment removed for export] *)
Section RVRA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x13 x15 x18 x19 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : amem) (WK wEnd mB T : Z).
  Variable Q : machine_state -> Prop.
  Hypothesis HWK : ablk WK (WK + 8704).
  Hypothesis HWE : 2 <= wEnd <= 13.
  Hypothesis HMB : 1 <= mB /\ T - mB <= 11.
  Hypothesis ZWK : zshadow m WK 8704.
  Hypothesis RWK : rng RNG WK 8704.
  Hypothesis RWKs : rng RNG (shad WK) (nshad (8704 + WK mod 8)).
  Notation WINV m1 rv c w := (rv_atA m1 WK rv (PRwA wEnd mB c w) /\ length rv = 156%nat
                           /\ (forall j, 1 <= j < wEnd -> 0 <= Znth j rv < 2^31)
                           /\ munch [(WK, WK + 624)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1).

  Lemma rvrA_inner : forall f c w rv m1 r (x6 x7 x12 : word),
    rank_val_row f c w rv = Ok r -> Z.of_nat f = wEnd - w -> 1 <= w < wEnd -> mB <= c <= T - mB -> WINV m1 rv c w ->
    (forall m2 rv' (y6 y7 y12 : word), r = rv' -> WINV m2 rv' c wEnd ->
       evtF asegs RNG Q
         (MS (mkR x1 (Z_to_bv 64 SPA) gp tp (Z_to_bv 64 (WK + 4 * wEnd)) y6 y7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA)
                  (Z_to_bv 64 (T - mB + 1)) (Z_to_bv 64 (WK + 4 * wEnd)) y12 (Z_to_bv 64 (WK + 4)) (Z_to_bv 64 (52 * c))
                  (Z_to_bv 64 (wEnd - 1)) (Z_to_bv 64 c) (Z_to_bv 64 0) x18 x19 x20 x21 x22 x23 (Z_to_bv 64 2147450880)
                  x25 x26 x27 x28 x29 x30 x31)
             F (Z_to_bv 64 0x819f4) fc None m2 (seg_rom asegs))) ->
    evtF asegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SPA) gp tp (Z_to_bv 64 (WK + 4 * w)) x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA)
               (Z_to_bv 64 (T - mB + 1)) (Z_to_bv 64 (WK + 4 * w)) x12 (Z_to_bv 64 (WK + 4)) (Z_to_bv 64 (52 * c))
               (Z_to_bv 64 (wEnd - 1)) (Z_to_bv 64 c) (Z_to_bv 64 (wEnd - w)) x18 x19 x20 x21 x22 x23 (Z_to_bv 64 2147450880)
               x25 x26 x27 x28 x29 x30 x31)
